using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
namespace Dafeiyu.Tests
{
 public static class UsageTrackingTests
 {
  static int passed,failed; static string root;
  public static int Main(){root=Path.Combine(Path.GetTempPath(),"deskpet-usage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
   Run("ledger merges snapshots and survives restart",async delegate{var s=Store();s.AddOrUpdate(new UsageRecord{RequestId="a",TimestampUtc=new DateTime(2026,10,17,16,1,0,DateTimeKind.Utc),InputTokens=10,Status="pending"});s.AddOrUpdate(new UsageRecord{RequestId="a",OutputTokens=5,Status="complete"});s.AddOrUpdate(new UsageRecord{RequestId="a",OutputTokens=5});var r=new UsageStore(Path.GetDirectoryName(Path.Combine(lastDirectory,"usage.jsonl"))).ReadAll().Single();Eq(10L,r.InputTokens);Eq(5L,r.OutputTokens);Eq(15L,r.TotalTokens);Eq("complete",r.Status);Eq(DateTimeKind.Utc,r.TimestampUtc.Kind);Eq(18,r.TimestampUtc.AddHours(8).Day);await Task.FromResult(true);});
   Run("snapshots are isolated and corrupt tail is ignored",async delegate{var s=Store();s.AddOrUpdate(new UsageRecord{RequestId="b",TimestampUtc=DateTime.UtcNow,Model="model"});s.ReadAll()[0].Model="changed";Eq("model",s.ReadAll()[0].Model);File.AppendAllText(Path.Combine(lastDirectory,"usage.jsonl"),"{broken\n");Eq(1,new UsageStore(lastDirectory).ReadAll().Count);await Task.FromResult(true);});
   Run("nonstream usage fields persist without secrets",async delegate{var s=Store();UsageTracking.Initialize(s);using(var server=new Server("{\"choices\":[{\"message\":{\"content\":\"private-reply\"}}],\"usage\":{\"prompt_tokens\":20,\"completion_tokens\":8,\"total_tokens\":28,\"prompt_tokens_details\":{\"cached_tokens\":7},\"completion_tokens_details\":{\"reasoning_tokens\":3}}}",false))using(var api=new ApiClient())using(UsageTracking.BeginScope("review","conversation","project")){await api.ChatAsync(server.Settings,new[]{new ChatMessage("user","private-prompt")},CancellationToken.None);}var r=s.ReadAll().Single();Eq(28L,r.TotalTokens);Eq(7L,r.CachedInputTokens);Eq(3L,r.ReasoningTokens);Eq("review",r.Feature);Eq("conversation",r.ConversationId);Eq("complete",r.Status);string json=File.ReadAllText(Path.Combine(lastDirectory,"usage.jsonl"));Assert(!json.Contains("private-prompt")&&!json.Contains("private-reply"),"saved message content");});
   Run("OpenAI stream cumulative updates merge once and request usage",async delegate{var s=Store();UsageTracking.Initialize(s);string body="data: {\"usage\":{\"prompt_tokens\":10,\"completion_tokens\":2},\"choices\":[{\"delta\":{\"content\":\"ok\"}}]}\n\ndata: {\"usage\":{\"prompt_tokens\":10,\"completion_tokens\":5,\"total_tokens\":15},\"choices\":[]}\n\ndata: [DONE]\n\n";using(var server=new Server(body,true))using(var api=new ApiClient()){await api.ChatStreamAsync(server.Settings,new[]{new ChatMessage("user","x")},null,CancellationToken.None);await server.Done;Assert(server.Body.Contains("include_usage"),"stream usage not requested");}Eq(15L,s.ReadAll().Single().TotalTokens);Eq(5L,s.ReadAll().Single().OutputTokens);});
   Run("Anthropic cache is included once and partial deltas retain input",async delegate{var s=Store();UsageTracking.Initialize(s);string body="data: {\"type\":\"message_start\",\"message\":{\"usage\":{\"input_tokens\":10,\"cache_read_input_tokens\":6,\"cache_creation_input_tokens\":4,\"output_tokens\":0}}}\n\ndata: {\"type\":\"content_block_delta\",\"delta\":{\"type\":\"text_delta\",\"text\":\"ok\"}}\n\ndata: {\"type\":\"message_delta\",\"usage\":{\"output_tokens\":5}}\n\ndata: {\"type\":\"message_stop\"}\n\n";using(var server=new Server(body,true))using(var api=new ApiClient()){server.Settings.Protocol="anthropic";await api.ChatStreamAsync(server.Settings,new[]{new ChatMessage("user","x")},null,CancellationToken.None);}var r=s.ReadAll().Single();Eq(20L,r.InputTokens);Eq(25L,r.TotalTokens);Eq(6L,r.CachedInputTokens);});
   Run("cancelled stream retains supplied usage",async delegate{var s=Store();UsageTracking.Initialize(s);using(var server=new Server("data: {\"usage\":{\"prompt_tokens\":9},\"choices\":[{\"delta\":{\"content\":\"ok\"}}]}\n\n",true))using(var api=new ApiClient())using(var c=new CancellationTokenSource()){try{await api.ChatStreamAsync(server.Settings,new[]{new ChatMessage("user","x")},d=>c.Cancel(),c.Token);}catch(OperationCanceledException){}}var r=s.ReadAll().Single();Eq(9L,r.InputTokens);Eq(null,r.OutputTokens);Eq(null,r.TotalTokens);Eq("cancelled",r.Status);});
   Run("parallel scope inheritance and restore do not leak",async delegate{var s=Store();UsageTracking.Initialize(s);var jobs=new List<Task>();using(UsageTracking.BeginScope("work","parent","project")){for(int i=0;i<8;i++){int n=i;jobs.Add(Task.Run(async delegate{using(UsageTracking.BeginScope(n%2==0?"subagent":"review")){await Task.Yield();using(var request=UsageTracking.BeginRequest(new ConnectionSettings{Model="m"},CancellationToken.None)){request.Observe(new Dictionary<string,object>{{"usage",new Dictionary<string,object>{{"prompt_tokens",n},{"completion_tokens",1}}}},false);request.Complete();}}}));}await Task.WhenAll(jobs);using(var request=UsageTracking.BeginRequest(new ConnectionSettings{Model="m"},CancellationToken.None)){request.Complete();}}using(var request=UsageTracking.BeginRequest(new ConnectionSettings{Model="m"},CancellationToken.None)){request.Complete();}var records=s.ReadAll();Eq(10,records.Count);Eq(4,records.Count(r=>r.Feature=="subagent"));Eq(4,records.Count(r=>r.Feature=="review"));Eq(1,records.Count(r=>r.Feature=="work"));Eq(1,records.Count(r=>r.Feature=="chat"));Assert(records.Where(r=>r.Feature!="chat").All(r=>r.ConversationId=="parent"),"lost inherited conversation");});
   Run("unknown usage and retries have distinct request ids",async delegate{var s=Store();UsageTracking.Initialize(s);for(int i=0;i<2;i++)using(var server=new Server("{\"choices\":[{\"message\":{\"content\":\"ok\"}}]}",false))using(var api=new ApiClient()){await api.ChatAsync(server.Settings,new[]{new ChatMessage("user","x")},CancellationToken.None);}Eq(2,s.ReadAll().Select(r=>r.RequestId).Distinct().Count());Assert(s.ReadAll().All(r=>!r.TotalTokens.HasValue&&!r.InputTokens.HasValue),"unknown became zero");});
   Run("actual measurements override estimates in either order",async delegate{var s=Store();s.AddOrUpdate(new UsageRecord{RequestId="actual",InputTokens=8,OutputTokens=2,IsEstimated=false});s.AddOrUpdate(new UsageRecord{RequestId="actual",InputTokens=80,OutputTokens=20,IsEstimated=true});Eq(10L,s.ReadAll().Single().TotalTokens);s.AddOrUpdate(new UsageRecord{RequestId="estimated",InputTokens=80,OutputTokens=20,IsEstimated=true});s.AddOrUpdate(new UsageRecord{RequestId="estimated",InputTokens=8,OutputTokens=2,IsEstimated=false});Eq(10L,s.ReadAll().Single(r=>r.RequestId=="estimated").TotalTokens);await Task.FromResult(true);});
   Run("writing after torn tail preserves new requests",async delegate{var s=Store();s.AddOrUpdate(new UsageRecord{RequestId="old"});File.AppendAllText(Path.Combine(lastDirectory,"usage.jsonl"),"{torn");s=new UsageStore(lastDirectory);s.AddOrUpdate(new UsageRecord{RequestId="new"});Eq(2,new UsageStore(lastDirectory).ReadAll().Count);await Task.FromResult(true);});
   Run("already cancelled operations create no request",async delegate{var s=Store();UsageTracking.Initialize(s);using(var cancel=new CancellationTokenSource()){cancel.Cancel();try{using(var request=UsageTracking.BeginRequest(new ConnectionSettings{Model="m"},cancel.Token))request.Complete();}catch(OperationCanceledException){}}Eq(0,s.ReadAll().Count);await Task.FromResult(true);});
   Run("failed stream retains preceding usage and has error status",async delegate{var s=Store();UsageTracking.Initialize(s);using(var server=new Server("data: {\"usage\":{\"prompt_tokens\":6,\"completion_tokens\":2},\"choices\":[{\"delta\":{\"content\":\"ok\"}}]}\n\n",true))using(var api=new ApiClient()){try{await api.ChatStreamAsync(server.Settings,new[]{new ChatMessage("user","x")},null,CancellationToken.None);throw new Exception("truncation accepted");}catch(ApiException){}}var r=s.ReadAll().Single();Eq(8L,r.TotalTokens);Eq("error",r.Status);});
   Run("native agent requests capture each response once for both transports",async delegate{foreach(bool stream in new[]{false,true}){var s=Store();UsageTracking.Initialize(s);string body=stream?"data: {\"choices\":[{\"delta\":{\"content\":\"ok\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":10,\"completion_tokens\":4}}\n\ndata: {\"choices\":[],\"usage\":{\"prompt_tokens\":10,\"completion_tokens\":4}}\n\ndata: [DONE]\n\n":"{\"choices\":[{\"message\":{\"content\":\"ok\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":10,\"completion_tokens\":4}}";using(var server=new Server(body,stream))using(var api=new ApiClient())using(UsageTracking.BeginScope("work","c","p")){await api.ChatAgentAsync(server.Settings,new[]{new ChatMessage("user","x")},null,null,null,null,stream,CancellationToken.None);}Eq(1,s.ReadAll().Count);Eq(14L,s.ReadAll().Single().TotalTokens);Eq("work",s.ReadAll().Single().Feature);}});
   Run("high-level helpers preserve distinct features and conversation attribution",async delegate{foreach(string feature in new[]{"chat","title","prediction","greeting","review"}){var ledger=Store();UsageTracking.Initialize(ledger);string text=feature=="prediction"?"[\"继续\"]":feature=="review"?"{\"decision\":\"allow\",\"reason\":\"ok\"}":"ok";using(var server=new Server(Response(text),false))using(var scope=UsageTracking.BeginScope("work","conversation","project")){var cfg=new PetSettings{Text=server.Settings,ReadReplies=false,AgentEnabled=false,ShowPredictedMessages=true,AiGreetingEnabled=true};if(feature=="review"){await new ApiAgentRiskReviewer(server.Settings).ReviewAsync(new AgentApprovalRequest{SessionId="conversation",ProjectId="project"},CancellationToken.None);}else if(feature=="greeting"){await new GreetingService().GenerateAsync(cfg,"pet","pet",new ChatMessage[0],DateTime.Now,0,new string[0],CancellationToken.None);}else using(var session=new ConversationSession(new ApiClient(),new Silent(),()=>null)){session.ConfigureKernelSession(new AgentSessionModel("conversation","project","conversation"),null);if(feature=="chat")await session.SendTextAsync("hello",cfg,"pet");else{session.History.Commit("hello","reply");if(feature=="title")await session.GenerateTitleAsync(cfg,CancellationToken.None);else await session.RequestPredictionsAsync(cfg);}}}var r=ledger.ReadAll().Single();Eq(feature,r.Feature);Eq("conversation",r.ConversationId);Eq("project",r.ProjectId);}});
   Run("worker HTTP accounting inherits parent identity without parent totals",async delegate{var ledger=Store();UsageTracking.Initialize(ledger);Directory.CreateDirectory(Path.Combine(root,"worker"));using(var server=new Server(Response("ok"),false))using(var scope=UsageTracking.BeginScope("work","conversation","project"))using(var workspace=new AgentWorkspace(Path.Combine(root,"worker"))){workspace.ConfigureKernel(AgentPermissionRuntime.DefaultWorkspacePolicy(),null,null,new ExecutionClaimStore(workspace.Root),"parent");workspace.BeginTask(new AgentTaskState{Id="parent",Workspace=workspace.Root,Goal="explore"});workspace.ConfigureWorkers(()=>new ApiClient(),server.Settings);workspace.ConfigureDesktopSession();var json=new System.Web.Script.Serialization.JavaScriptSerializer();string spawned=await workspace.ExecuteAsync("spawn_subagent","{\"profile\":\"explore\",\"input\":\"inspect\"}","spawn",CancellationToken.None);Assert(spawned.StartsWith("{"),spawned);var child=(Dictionary<string,object>)json.DeserializeObject(spawned);string id=(string)child["Id"];await workspace.ExecuteAsync("wait_subagents",json.Serialize(new{ids=new[]{id},timeout_seconds=5}),"wait",CancellationToken.None);}var record=ledger.ReadAll().Single();Eq("subagent",record.Feature);Eq("conversation",record.ConversationId);Eq(10L,record.TotalTokens);});
   Run("ledger writes stable ISO UTC dates for both runtimes",async delegate{var s=Store();s.AddOrUpdate(new UsageRecord{RequestId="iso",TimestampUtc=new DateTime(2026,10,17,16,1,0,DateTimeKind.Utc)});string text=File.ReadAllText(Path.Combine(lastDirectory,"usage.jsonl"));Assert(text.Contains("2026-10-17T16:01:00.0000000Z"),"runtime-specific date format persisted");await Task.FromResult(true);});
   Run("storage failure keeps pending records and recovers without breaking callers",async delegate{string directory=Path.Combine(root,"blocked");File.WriteAllText(directory,"conflict");var s=new UsageStore(directory);s.AddOrUpdate(new UsageRecord{RequestId="pending",InputTokens=3});var property=typeof(UsageStore).GetProperty("Warning");Assert(property!=null&&!String.IsNullOrEmpty(property.GetValue(s,null) as string),"storage failure hidden");Eq(1,s.ReadAll().Count);File.Delete(directory);s.AddOrUpdate(new UsageRecord{RequestId="next",OutputTokens=4});Assert(String.IsNullOrEmpty(property.GetValue(s,null) as string),"warning not cleared after recovery");Eq(2,new UsageStore(directory).ReadAll().Count);await Task.FromResult(true);});
   Run("large journal compacts without losing requests or cumulative snapshots",async delegate{var s=Store();s.AddOrUpdate(new UsageRecord{RequestId="large",InputTokens=3,OutputTokens=2});string file=Path.Combine(lastDirectory,"usage.jsonl"),row=File.ReadAllText(file);var text=new StringBuilder();while(text.Length<5*1024*1024)text.Append(row);File.WriteAllText(file,text.ToString());s=new UsageStore(lastDirectory);s.AddOrUpdate(new UsageRecord{RequestId="large",OutputTokens=4});s.AddOrUpdate(new UsageRecord{RequestId="second",InputTokens=2});Assert(new FileInfo(file).Length<10000,"journal grew without compaction");var reopened=new UsageStore(lastDirectory);Eq(2,reopened.ReadAll().Count);Eq(7L,reopened.ReadAll().Single(r=>r.RequestId=="large").TotalTokens);await Task.FromResult(true);});
   Run("locked history is retried without discarding earlier or pending records",async delegate{var first=Store();string directory=lastDirectory;first.AddOrUpdate(new UsageRecord{RequestId="history",InputTokens=5});UsageStore s;using(var locked=new FileStream(Path.Combine(directory,"usage.jsonl"),FileMode.Open,FileAccess.ReadWrite,FileShare.None)){s=new UsageStore(directory);Assert(!String.IsNullOrEmpty(s.Warning),"read failure hidden");s.AddOrUpdate(new UsageRecord{RequestId="during-lock",OutputTokens=2});Eq(1,s.ReadAll().Count);}s.AddOrUpdate(new UsageRecord{RequestId="after-lock"});Eq("",s.Warning);Eq(3,new UsageStore(directory).ReadAll().Count);await Task.FromResult(true);});
   Run("Anthropic partial cache snapshots reconcile against raw input once",async delegate{var ledger=Store();UsageTracking.Initialize(ledger);using(var request=UsageTracking.BeginRequest(new ConnectionSettings{Model="m"},CancellationToken.None)){request.Observe(new Dictionary<string,object>{{"usage",new Dictionary<string,object>{{"input_tokens",10},{"output_tokens",0}}}},true);request.Observe(new Dictionary<string,object>{{"usage",new Dictionary<string,object>{{"cache_read_input_tokens",6},{"output_tokens",2}}}},true);request.Observe(new Dictionary<string,object>{{"usage",new Dictionary<string,object>{{"cache_read_input_tokens",6},{"output_tokens",2}}}},true);request.Complete();}Eq(16L,ledger.ReadAll().Single().InputTokens);Eq(18L,ledger.ReadAll().Single().TotalTokens);await Task.FromResult(true);});
   Run("unknown pending records accept estimates and status updates retain their source",async delegate
   {
       var ledger=Store();string directory=lastDirectory;
       ledger.AddOrUpdate(new UsageRecord{RequestId="source-transition",Status="pending"});
       ledger.AddOrUpdate(new UsageRecord{RequestId="source-transition",InputTokens=80,OutputTokens=20,IsEstimated=true});
       var snapshot=ledger.ReadAll().Single();
       Eq(100L,snapshot.TotalTokens);Eq(true,snapshot.IsEstimated);
       ledger.AddOrUpdate(new UsageRecord{RequestId="source-transition",Status="complete"});
       snapshot=new UsageStore(directory).ReadAll().Single();
       Eq(100L,snapshot.TotalTokens);Eq(true,snapshot.IsEstimated);Eq("complete",snapshot.Status);
       // A later partial actual measurement replaces the estimate without mixing sources.
       ledger.AddOrUpdate(new UsageRecord{RequestId="source-transition",InputTokens=8});
       snapshot=ledger.ReadAll().Single();
       Eq(8L,snapshot.InputTokens);Eq(null,snapshot.OutputTokens);Eq(null,snapshot.TotalTokens);Eq(false,snapshot.IsEstimated);
       ledger.AddOrUpdate(new UsageRecord{RequestId="source-transition",OutputTokens=2});
       ledger.AddOrUpdate(new UsageRecord{RequestId="source-transition",InputTokens=800,OutputTokens=200,IsEstimated=true});
       snapshot=new UsageStore(directory).ReadAll().Single();
       Eq(10L,snapshot.TotalTokens);Eq(false,snapshot.IsEstimated);
       await Task.FromResult(true);
   });
   Run("measured zero remains actual when a later estimate arrives",async delegate
   {
       var ledger=Store();ledger.AddOrUpdate(new UsageRecord{RequestId="actual-zero",InputTokens=0,OutputTokens=0});
       ledger.AddOrUpdate(new UsageRecord{RequestId="actual-zero",InputTokens=80,OutputTokens=20,IsEstimated=true});
       var snapshot=ledger.ReadAll().Single();Eq(0L,snapshot.TotalTokens);Eq(false,snapshot.IsEstimated);
       await Task.FromResult(true);
   });
   UsageTracking.Initialize(null);Console.WriteLine("UsageTrackingTests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;
  }
  static string Response(string text){return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{choices=new[]{new{message=new{content=text},finish_reason="stop"}},usage=new{prompt_tokens=8,completion_tokens=2}});}
  sealed class Silent:IReplySpeech{public Task SpeakAsync(string text,PetSettings settings,CancellationToken token){return Task.FromResult(0);}public void SetVolume(int volume){}public void Stop(){}public void Dispose(){}}
  static string lastDirectory;static UsageStore Store(){lastDirectory=Path.Combine(root,Guid.NewGuid().ToString("N"));return new UsageStore(lastDirectory);}
  static void Run(string name,Func<Task> f){try{f().GetAwaiter().GetResult();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e);}}
  static void Eq(object a,object b){if(!Object.Equals(a,b))throw new Exception("Expected "+a+", actual "+b);}static void Assert(bool b,string m){if(!b)throw new Exception(m);}
  sealed class Server:IDisposable
  {readonly HttpListener listener=new HttpListener();public readonly ConnectionSettings Settings;public readonly Task Done;public string Body;
   public Server(string body,bool stream){var probe=new System.Net.Sockets.TcpListener(IPAddress.Loopback,0);probe.Start();int port=((System.Net.IPEndPoint)probe.LocalEndpoint).Port;probe.Stop();string url="http://127.0.0.1:"+port+"/";Settings=new ConnectionSettings{BaseUrl=url,Model="test-model",Protocol="auto"};listener.Prefixes.Add(url);listener.Start();Done=Task.Run(async delegate{try{var ctx=await listener.GetContextAsync();using(var reader=new StreamReader(ctx.Request.InputStream))Body=await reader.ReadToEndAsync();byte[] bytes=Encoding.UTF8.GetBytes(body);ctx.Response.ContentType=stream?"text/event-stream":"application/json";ctx.Response.ContentLength64=bytes.Length;await ctx.Response.OutputStream.WriteAsync(bytes,0,bytes.Length);ctx.Response.Close();}catch(HttpListenerException){}catch(ObjectDisposedException){}});}
   public void Dispose(){listener.Close();}
  }
 }
}
